"""Leakage-safe Cui/Wang experiments on logs generated by the closed-manager stand."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import math
import platform
import subprocess
import sys
import time
import importlib
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[2]
STAND_DIR = ROOT / "benchmarks" / "closed_stand"
sys.path.insert(0, str(STAND_DIR))
stand = importlib.import_module("stand")
RandomShare = importlib.import_module("routers").RandomShare


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def environment_hash():
    files = [ROOT / "articles_prorotypes" / name for name in
             ("bench/stand_benchmark.py", "cui/cui2011.py", "cui/cui_features.py", "wang/wang2016.py")]
    files += [STAND_DIR / "stand.py", STAND_DIR / "seller.py", STAND_DIR.parent / "log_benchmark" / "ads.py"]
    return {str(path.relative_to(ROOT)): sha256(path) for path in files}


def response_metrics(labels, probabilities):
    labels = np.asarray(labels, dtype=bool)
    probabilities = np.clip(np.asarray(probabilities, dtype=float), 1e-12, 1 - 1e-12)
    bins = []
    for low, high in zip(np.linspace(0, 1, 11)[:-1], np.linspace(0, 1, 11)[1:]):
        mask = (probabilities >= low) & ((probabilities < high) | ((high == 1) & (probabilities <= high)))
        bins.append({"lower": float(low), "upper": float(high), "count": int(mask.sum()),
                     "mean_predicted": float(probabilities[mask].mean()) if mask.any() else None,
                     "observed_rate": float(labels[mask].mean()) if mask.any() else None})
    return {"brier": float(np.mean((probabilities - labels) ** 2)),
            "log_loss": float(-np.mean(labels*np.log(probabilities) + (~labels)*np.log1p(-probabilities))),
            "calibration_bins": bins}


def _hash_payload(values):
    return hashlib.sha256(np.ascontiguousarray(values).view(np.uint8)).hexdigest()


def run(args):
    prep = stand.load_prepared(args.prepared)
    out = Path(args.output_dir)
    out.mkdir(parents=True, exist_ok=True)
    source_files = [Path(prep.root) / f"{day['name']}_{field}.npy"
                    for day in prep.meta["days"] for field in ("ts", "user", "combo")]
    source_hashes = {str(path): sha256(path) for path in source_files}
    pool_mask = stand.pool_mask_of(prep, stand.POOL_DEVICES)
    ads_hashes = {"manager_ads_sha256": sha256(args.manager_ads), "our_ads_sha256": sha256(args.our_ads)}
    manager_ads = stand.load_ads_file(args.manager_ads)
    our_ads = stand.load_ads_file(args.our_ads)
    ads_hashes = {"manager_ads_sha256": sha256(args.manager_ads), "our_ads_sha256": sha256(args.our_ads)}
    records, phase_summaries, log_hashes = [], [], {}
    sample = min(1.0, args.max_requests / sum(len(prep.day_arrays(d)[0])
                  for d in range(args.days[0], args.days[1])))
    for seed in args.seeds:
        # The actual stand does the simulation/log generation; all outcomes originate in Seller.
        q = args.q
        manager_log, pool_log = [], []
        phase_logs = {}
        for start, end, phase in [(args.days[0], args.days[1], "training"),
                                  (args.validation_days[0], args.validation_days[1], "validation"),
                                  (args.test_days[0], args.test_days[1], "test")]:
            result = stand.simulate(prep, (start, end), sample, manager_ads, our_ads, pool_mask, q,
                                    lambda: RandomShare(pool_mask, prep.combos, q, seed), args.manager_price,
                                    seed=seed, collect_log=True, progress=None)
            log = result.pop("_log")
            phase_logs[phase] = log
            phase_summaries.append({"seed": seed, "phase": phase, "days": [start, end],
                                    "requests_evaluated": result["requests"], "pool_requests": result["pool"],
                                    "sent": result["sent"], "responses_200": result["ok"],
                                    "sellthrough": result["sellthrough"], "seconds": result["seconds"]})
        train_log = phase_logs["training"]
        # Materialize actual logs verbatim. These contain only sent request features and 200/204 response.
        for phase, (lts, lusers, lcombos, lstatus) in phase_logs.items():
            path = out / f"seed_{seed}_{phase}.parquet"
            stand.write_log(str(path), prep, (lts, lusers, lcombos, lstatus))
            log_hashes[str(path)] = sha256(path)
        train_log, val_log, test_log = (phase_logs[p] for p in ("training", "validation", "test"))
        train_y, val_y, test_y = (log[3] == 200 for log in (train_log, val_log, test_log))
        train_rate, val_rate = float(np.mean(train_y)), float(np.mean(val_y))
        train_hash = _hash_payload(np.column_stack((train_log[0], train_log[1], train_log[2], train_log[3])))
        val_hash = _hash_payload(np.column_stack((val_log[0], val_log[1], val_log[2], val_log[3])))
        test_hash = _hash_payload(np.column_stack((test_log[0], test_log[1], test_log[2], test_log[3])))
        for name, probability, selection in (
            ("TRAIN_CONSTANT", train_rate, None),
            ("VALIDATION_SELECTED_CONSTANT", val_rate, {"selection_metric": "validation_log_loss",
                                                        "selected_probability": val_rate,
                                                        "validation_rows": len(val_y)}),
        ):
            records.append({"seed": seed, "article": "stand_response_baseline", "model": name,
                            "train_rows": len(train_y), "validation_rows": len(val_y), "test_rows": len(test_y),
                            "test_coverage": len(test_y), "fit_seconds": 0.0, "predict_seconds": 0.0,
                            "train_sha256": train_hash, "validation_sha256": val_hash, "test_sha256": test_hash,
                            "validation_selection": selection, "train_positive_rate": train_rate,
                            "validation_positive_rate": val_rate, "test_positive_rate": float(np.mean(test_y)),
                            **response_metrics(test_y, np.full(len(test_y), probability))})
        for paper in ("Cui2011", "Wang2016"):
            records.append({"seed": seed, "article": paper, "model": None, "status": "not_evaluable_on_stand_schema",
                            "reason": "stand emits 200/204 response, not observed campaign bids, submitted bids or external market prices"})
    payload = {"title": "Closed-stand generated response logs; no valid market-price benchmark labels",
               "environment": {"python": platform.python_version(), "platform": platform.platform()},
               "numpy": np.__version__, "processor": platform.processor(),
               "generator": "benchmarks/closed_stand/stand.py::simulate + Seller",
               "prepared_signature": stand.prepared_signature(prep), "prepared_source": prep.meta.get("source"),
               "generator_command": f"{sys.executable} -m articles_prorotypes.bench.stand_benchmark --prepared {args.prepared} --manager-ads {args.manager_ads} --our-ads {args.our_ads} --output-dir {args.output_dir} --seeds {','.join(map(str,args.seeds))} --max-requests {args.max_requests} --days {args.days[0]}:{args.days[1]} --validation-days {args.validation_days[0]}:{args.validation_days[1]} --test-days {args.test_days[0]}:{args.test_days[1]} --q {args.q} --manager-price {args.manager_price}",
               "prepared_source_sha256": sha256(Path(args.prepared) / "meta.json"),
               "stand_source_sha256": {str(path.relative_to(ROOT)): sha256(path) for path in
                                         (STAND_DIR / "stand.py", STAND_DIR / "seller.py",
                                          STAND_DIR.parent / "log_benchmark" / "ads.py",
                                          ROOT / "articles_prorotypes" / "bench" / "stand_benchmark.py")},
               "git_commit": subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True, text=True).stdout.strip() or None,
               "dirty_worktree": bool(subprocess.run(["git", "status", "--porcelain"], cwd=ROOT, capture_output=True, text=True).stdout.strip()),
               "prepared_file_sha256": source_hashes, "code_sha256": environment_hash(), **ads_hashes,
               "requested_max_requests_per_seed_training_period": args.max_requests,
                "seeds": args.seeds, "sample_fraction": sample,
               "manager_price": args.manager_price, "manager_price_semantics": "internal fixed payout for response 200, never interpreted as auction clearing price",
               "split_days": {"training": args.days, "validation": args.validation_days, "test": args.test_days},
                "phases": phase_summaries, "generated_log_sha256": log_hashes, "results": records,
               "limitations": ["closed stand outputs manager's simulated 200/204 response only; no independent market-price labels",
                                "Wang exact-price ANLP/CDF cannot be validly computed: no market price or censored submitted-bid threshold exists",
                                "Cui winning-bid/campaign bid landscape also cannot be evaluated on this schema",
                                "Wang MM cannot be evaluated here; the Wang source only gives a brief description and external Wu et al. (2015) method, not a sufficient implementation specification"]}
    json_path = out / "results.json"
    json_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    lines = ["# Stand log results", "", payload["title"], "",
             f"Generator: `{payload['generator']}`; sample={sample:.6f}; seeds={args.seeds}.",
             "The stand's price of 200 is an internal fixed payout. It is not a clearing price and is never used as a market-price label.", "",
             "## Generated periods", "",
             "| seed | phase | days | processed | sent | 200 | sell-through | seconds |",
             "|---:|---|---|---:|---:|---:|---:|---:|"]
    lines += [f"| {x['seed']} | {x['phase']} | {x['days'][0]}:{x['days'][1]} | {x['requests_evaluated']} | {x['sent']} | {x['responses_200']} | {x['sellthrough']:.4f} | {x['seconds']:.2f} |" for x in phase_summaries]
    lines += ["", "## Models and scores", "", "| seed | paper / scope | variant | train | test | Brier | log-loss | fit (s) | predict (s) |",
              "|---:|---|---|---:|---:|---:|---:|---:|---:|"]
    for row in records:
        lines.append(f"| {row['seed']} | {row['article']} | {row['model'] or row['status']} | {row.get('train_rows','')} | {row.get('test_rows','')} | {row.get('brier','')} | {row.get('log_loss','')} | {row.get('fit_seconds','')} | {row.get('predict_seconds','')} |")
    lines += ["", "## Interpretation limits", ""] + [f"- {issue}." for issue in payload["limitations"]]
    (out / "results.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    return payload


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--prepared", default=str(ROOT / "benchmarks/logs/prepared_20261012_retry"))
    parser.add_argument("--manager-ads", default=str(STAND_DIR / "manager_target50_20261012.json"))
    parser.add_argument("--our-ads", default=str(ROOT / "benchmarks/log_benchmark/ads_manual.json"))
    parser.add_argument("--output-dir", default=str(Path(__file__).resolve().parents[3] / "docs/benchmark/bid_forecast/results/stand_logs"))
    parser.add_argument("--seeds", type=lambda x: [int(v) for v in x.split(",")], default=[19, 43, 71])
    parser.add_argument("--max-requests", type=int, default=30000)
    parser.add_argument("--days", type=lambda x: tuple(map(int, x.split(":"))), default=(0, 3))
    parser.add_argument("--validation-days", type=lambda x: tuple(map(int, x.split(":"))), default=(3, 5))
    parser.add_argument("--test-days", type=lambda x: tuple(map(int, x.split(":"))), default=(5, 7))
    parser.add_argument("--q", type=float, default=.8)
    parser.add_argument("--manager-price", type=float, default=150)
    args = parser.parse_args(argv)
    result = run(args)
    print(f"saved {args.output_dir}: {len(result['phases'])} stand phases, {len(result['results'])} model records")


if __name__ == "__main__":
    main()
